let state;try{state=JSON.parse(localStorage.getItem(key))||defaults();}catch{state=defaults();}
state.profile ||= "general";state.channel ||= {};state.supportRequests ||= [];state.syncReceipts ||= [];const currentOrder=()=>marketOrder(state.session)|| (state.profile==="bonfim"?demoOrder:null);const currentPool=()=>currentOrder()?poolLots(marketOrder(state.session)?marketPoolLots(state.lots,currentOrder()):state.lots,currentOrder()):{allocations:[],quantityKg:0,shortfallKg:0,matched:false};
