$('#create-handover').onclick=()=>{if(!currentOrder())return toast('Selecione um pedido antes de criar o repasse.');const exporter=$('#exporter').value.trim();if(!exporter)return toast('Enter an exporter or coordinator name.');const selected=state.choices.filter(c=>c.choice==='cross-border-proposal'&&c.orderId===currentOrder().id);if(!selected.length)return toast('At least one farmer must explicitly select the proposal first.');state.handovers.push({id:crypto.randomUUID(),createdAt:new Date().toISOString(),exporter,notes:$('#handover-note').value,order:currentOrder(),farmerChoices:selected,lots:state.lots.filter(l=>selected.some(c=>c.lotId===l.id)),quantityKg:selected.reduce((s,c)=>s+c.quantityKg,0),fullFarmerConsent:selected.reduce((s,c)=>s+c.quantityKg,0)===currentOrder().quantityKg,status:'awaiting buyer confirmation and trade-requirement checks',checks:{buyerConfirmation:'pending',tradeRequirements:'unchecked',exporterEligibility:'unchecked',quality:'unconfirmed',transport:'unconfirmed',payment:'unconfirmed'},dispatchAuthorized:false});persist();render();toast('Handover saved. Only consenting farmers included.');};
$('#download-handover').onclick=()=>state.handovers.length?download('harvestlink-exporter-handover.json',state.handovers.at(-1)):toast('Save a handover first.');
$('#benchmark').onclick=()=>{const samples=['Sou Ana, tenho 120 kg de tomate, classe A','Quero comparar ganhos da venda local','confirmo minha colheita','cancelar lote'];const times=[];for(let i=0;i<20;i++)classify(samples[i%4],model);for(let i=0;i<100;i++){const t=performance.now();handleMessage(samples[i%4],{draft:{}},model);times.push(performance.now()-t);}times.sort((a,b)=>a-b);const physical=$('#physical-device').checked;state.benchmarks.push({recordedAt:new Date().toISOString(),model:model.name,modelBytes,modelPackBytes:model.modelBytes,runtimeBytes:model.runtimeBytes,assets:model.assetSizes,algorithm:'binary character 3–5 grams + learned logistic regression',training:'72 synthetic EN/PT messages; not farmer accuracy evidence',ramGb:$('#device-ram').value?Number($('#device-ram').value):null,heapBytes:performance.memory?.usedJSHeapSize||null,heapLimitations:'Optional whole-browser JS heap, not model working RAM',samples:100,warmup:20,p50Ms:times[49],p95Ms:times[94],maxMs:times[99],measurement:'intent classification + field extraction + response generation; excludes rendering',device:$('#device').value||'unspecified',physicalAndroidSelfReported:physical,airplaneModeSelfReported:$('#airplane-attest').checked,browserReportsOnline:navigator.onLine,userAgent:navigator.userAgent,proofType:physical?'self-reported device run; external video still required':'browser measurement — not Android proof'});persist();render();toast('Benchmark saved.');};
$('#persist-storage').onclick=async()=>{try{const granted=await navigator.storage?.persist?.();state.storageEvidence={requestedAt:new Date().toISOString(),persistent:!!granted,estimate:await navigator.storage?.estimate?.()};persist();$('#storage-evidence').textContent=granted?'Persistent storage granted. Clearing site data still removes records.':'Persistent storage was not granted. Keep an exported backup.';}catch(e){toast(e.message);}};
$('#export-evidence').onclick=()=>download('harvestlink-evidence.json',{...state,modelBytes,exportedAt:new Date().toISOString(),proofLimitations:['No physical airplane-mode proof from browser alone','Provider accepted messages are not delivery proof','Template bilingual reviewer sign-off pending','Prices/orders/costs/FX are demonstration assumptions']});
async function api(path,method='GET',body){const token=$('#api-key').value;if(!token)throw Error('Enter operator API key.');const response=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},body:body?JSON.stringify(body):undefined});const result=await response.json();if(!response.ok)throw Error(result.error||'Request failed');return result;}
$('#sync').onclick=async()=>{try{const result=await api('sync','POST',{lots:state.lots,choices:state.choices,handovers:state.handovers});state.syncReceipts.push({at:new Date().toISOString(),lots:state.lots.map(l=>l.id),choices:state.choices.map(c=>c.id),fingerprints:Object.fromEntries(state.lots.map(l=>[l.id,JSON.stringify(l)]))});persist();render();toast(`Synced ${result.lots} lots. Explicit online sync completed.`);}catch(e){toast(e.message);}};
$('#load-messages').onclick=async()=>{try{const data=await api('messages');$('#messaging-status').textContent=data.configured?'Twilio configured. Provider evidence below.':'Provider not configured. No real exchange yet.';$('#provider-messages').innerHTML=data.messages.map(m=>card(`${m.kind} · ${m.sid} · ${m.status||''} · ${m.body||m.reply||''} · ${m.at}`)).join('')||card('No provider messages recorded.');$('#provider-accounts').innerHTML=(data.accounts||[]).map(a=>card(a.name+' · '+a.location+' · ID '+a.id.slice(0,8))).join('')+(data.supportRequests||[]).map(r=>card('Apoio · '+r.farmerId.slice(0,8)+' · '+r.createdAt+' · '+r.status)).join('');for(const l of data.lots)if(!state.lots.some(x=>x.id===l.id))state.lots.push(l);persist();render();}catch(e){toast(e.message);}};
$('#send-provider').onclick=async()=>{try{const result=await api('send','POST',{to:$('#provider-to').value,body:$('#provider-body').value});toast(`Provider accepted message ${result.sid} (${result.status}); delivery not yet proven.`);}catch(e){toast(e.message);}};
$('#export-account').onclick=()=>{const account=state.session.account;if(!account)return toast('Crie seu perfil primeiro.');const lots=state.lots.filter(l=>l.farmerId===account.id);download('harvestlink-my-account.json',{account,lots,choices:state.choices.filter(c=>lots.some(l=>l.id===c.lotId)),supportRequests:state.supportRequests.filter(r=>r.farmerId===account.id),exportedAt:new Date().toISOString(),delivery:'Local records; export does not send to a buyer'});};
function channelLinks(){for(const id of ['whatsapp-number','whatsapp-join','sms-number'])$('#'+id).value=state.channel[id]||'';const number=state.channel['whatsapp-number']||'',sms=state.channel['sms-number']||'';const wa=$('#open-whatsapp'),sm=$('#open-sms');wa.removeAttribute('href');sm.removeAttribute('href');if(/^\+[1-9]\d{7,14}$/.test(number))wa.href='https://wa.me/'+number.slice(1)+'?text='+encodeURIComponent(state.channel['whatsapp-join']||'AJUDA');if(/^\+[1-9]\d{7,14}$/.test(sms))sm.href='sms:'+sms+'?body='+encodeURIComponent('AJUDA');for(const a of [wa,sm])a.setAttribute('aria-disabled',String(!a.hasAttribute('href')));}
$('#save-channel').onclick=()=>{const next={};for(const id of ['whatsapp-number','whatsapp-join','sms-number'])next[id]=$('#'+id).value.trim();if([next['whatsapp-number'],next['sms-number']].some(n=>n&&!/^\+[1-9]\d{7,14}$/.test(n)))return toast('Use o formato internacional: + seguido do código do país e número.');state.channel=next;persist();channelLinks();toast('Conexão salva neste telefone. Abra o canal e envie a mensagem.');};channelLinks();
function connectivity(){$('#connection').textContent=navigator.onLine?'● Conectado · AI local':'● Offline · AI local';}window.addEventListener('online',connectivity);window.addEventListener('offline',connectivity);connectivity();render();linking=installLinking({state,persist,render,toast,download});installLanguageSwitch();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js?release=v23').then(()=>navigator.serviceWorker.ready).then(()=>toast('Offline cache installed, including the small AI. Reload once, then test airplane mode.')).catch(e=>toast('Offline cache unavailable: '+e.message));


function renderMarketplace(){
 const view=state.marketCache||state.shared?.snapshot?.marketplace||marketView(state.session,state.lots,state.choices,state.handovers);
 $('#market-status').textContent=(navigator.onLine?'Online':'Offline · cached snapshot')+' · '+(view.observedAt||'')+' · DEMONSTRATION ONLY';
 const orders=view.orders||[];
 $('#market-cards').innerHTML=orders.map(o=>'<article class="offer-row"><div><p class="eyebrow">'+esc(o.id)+' · DEMO</p><h3>'+esc(crops[o.crop]?.[state.session.account?.language==='pt'?'pt':'en']||o.crop)+'</h3><p>'+esc(o.sourceLocation)+' → '+esc(o.destination)+'</p></div><div class="offer-terms"><strong>'+esc(o.quantityKg)+' kg</strong><span>GYD '+esc(o.priceGydKg)+'/kg</span></div><p class="muted">'+esc(o.buyer)+'</p></article>').join('')+(view.enabled?card('Pool '+view.pooledKg+'/'+view.order.quantityKg+' kg · '+view.syntheticKg+' kg fictional partner · '+view.shortfallKg+' kg missing')+card('Your allocations: '+view.ownAllocations.map(a=>a.kg+' kg · local BRL '+a.localNet.toFixed(2)+' · proposal BRL '+a.crossNet.toFixed(2)).join('; '))+card('Logistics: '+view.transport.route+' · '+view.transport.carrier+' · '+view.transport.pickup+' · BRL '+view.transport.transportBrlKg+'/kg · not booked')+card('Import / export: '+view.trade.exporter+' · '+JSON.stringify(view.trade.checks))+card(view.status+' · No dispatch authorized')+view.handovers.map(h=>card('Handover '+h.id.slice(0,8)+' · '+h.quantityKg+' kg · '+h.status)).join(''):card('Send DEMO MARKET in WhatsApp to activate the fictional example.'));
}
$('#refresh-market').onclick=async()=>{try{if(!linking?.marketplace)throw Error('Link your WhatsApp account first.');state.marketCache=await linking.marketplace();persist();renderMarketplace();}catch(e){toast(e.message);}};
setInterval(()=>{if(!$('#marketplace').hidden&&navigator.onLine&&state.shared?.token)$('#refresh-market').click();},15000);
